package com.wipro.hibernate;import org.hibernate.*;import java.math.*;import java.util.*;public class Main{public static void main(String[]x){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();Emp e=new Emp();e.setEmpno(8001);e.setEname("MEENAKSHI");e.setJob("ENGINEER");e.setMgr(7839);e.setHiredate(new Date());e.setSal(new BigDecimal("50000"));e.setComm(BigDecimal.ZERO);e.setDeptno(10);s.persist(e);t.commit();System.out.println("Employee record inserted successfully.");}HibernateUtil.getSessionFactory().close();}}